CREATE OR REPLACE FUNCTION public.create_agency(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND NOT suspended) THEN RAISE EXCEPTION 'Authentication required'; END IF; IF (SELECT count(*) FROM public.agencies WHERE owner_id=auth.uid())>=3 THEN RAISE EXCEPTION 'Organization limit reached'; END IF; INSERT INTO public.agencies(name,owner_id) VALUES(trim(_name),auth.uid()) RETURNING id INTO aid; INSERT INTO public.agency_members(agency_id,user_id,role) VALUES(aid,auth.uid(),'agency_admin'); INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'agency_admin') ON CONFLICT DO NOTHING; INSERT INTO public.subscriptions(agency_id) VALUES(aid); INSERT INTO public.audit_logs(agency_id,actor_id,action,entity,entity_id) VALUES(aid,auth.uid(),'CREATE','agencies',aid); RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.create_agency(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_agency(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.invite_agency_member(_agency uuid,_email text,_role text,_case uuid DEFAULT NULL,_permissions text[] DEFAULT ARRAY['general','documents','appointments','messages']) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE iid uuid; BEGIN IF NOT public.agency_access(_agency,true) THEN RAISE EXCEPTION 'Agency administrator required'; END IF; IF _case IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cases WHERE id=_case AND agency_id=_agency) THEN RAISE EXCEPTION 'Case not in agency'; END IF; IF _case IS NULL AND _role NOT IN('agency_admin','agency_staff','professional','clinic_staff') THEN RAISE EXCEPTION 'Invalid team role'; END IF; IF _case IS NOT NULL AND _role NOT IN('intended_parent','carrier','professional','clinic_staff','case_manager') THEN RAISE EXCEPTION 'Invalid case role'; END IF; IF _permissions IS NULL OR NOT _permissions <@ ARRAY['general','documents','appointments','messages','medical','legal','finance','incidents','audit'] THEN RAISE EXCEPTION 'Invalid permissions'; END IF; IF _email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF; IF (SELECT count(*) FROM public.agency_invitations WHERE invited_by=auth.uid() AND created_at>now()-interval '1 hour')>=30 THEN RAISE EXCEPTION 'Invitation limit reached'; END IF; INSERT INTO public.agency_invitations(agency_id,case_id,email,role,permissions,invited_by) VALUES(_agency,_case,lower(trim(_email)),_role,_permissions,auth.uid()) RETURNING id INTO iid; INSERT INTO public.audit_logs(agency_id,case_id,actor_id,action,entity,entity_id) VALUES(_agency,_case,auth.uid(),'INVITE','agency_invitations',iid); RETURN iid; END $$;
REVOKE ALL ON FUNCTION public.invite_agency_member(uuid,text,text,uuid,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invite_agency_member(uuid,text,text,uuid,text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.accept_agency_invitation(_invitation uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.agency_invitations; BEGIN SELECT * INTO inv FROM public.agency_invitations WHERE id=_invitation FOR UPDATE; IF inv.id IS NULL OR inv.status<>'pending' OR inv.expires_at<now() OR lower(inv.email)<>lower(auth.jwt()->>'email') OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF inv.case_id IS NULL THEN INSERT INTO public.agency_members(agency_id,user_id,role) VALUES(inv.agency_id,auth.uid(),inv.role) ON CONFLICT(agency_id,user_id) DO UPDATE SET active=true,role=excluded.role; ELSE INSERT INTO public.case_participants(case_id,user_id,role,permissions) VALUES(inv.case_id,auth.uid(),inv.role,inv.permissions) ON CONFLICT(case_id,user_id) DO UPDATE SET active=true,role=excluded.role,permissions=excluded.permissions; END IF; UPDATE public.agency_invitations SET status='accepted' WHERE id=inv.id; INSERT INTO public.audit_logs(agency_id,case_id,actor_id,action,entity,entity_id) VALUES(inv.agency_id,inv.case_id,auth.uid(),'ACCEPT','agency_invitations',inv.id); RETURN inv.agency_id; END $$;
REVOKE ALL ON FUNCTION public.accept_agency_invitation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_agency_invitation(uuid) TO authenticated;
CREATE SEQUENCE public.case_reference_seq START 100;
CREATE OR REPLACE FUNCTION public.create_agency_case(_agency uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; lim integer; BEGIN IF NOT public.agency_access(_agency,true) THEN RAISE EXCEPTION 'Agency administrator required'; END IF; SELECT CASE plan WHEN 'starter' THEN 5 WHEN 'professional' THEN 15 WHEN 'growth' THEN 40 ELSE 100000 END INTO lim FROM public.agencies WHERE id=_agency; IF (SELECT count(*) FROM public.cases WHERE agency_id=_agency AND status<>'closed')>=lim THEN RAISE EXCEPTION 'Active case limit reached'; END IF; INSERT INTO public.cases(reference,parent_id,agency_id,case_manager_id,journey_stage) VALUES('NF-'||extract(year FROM now())::text||'-'||lpad(nextval('public.case_reference_seq')::text,3,'0'),auth.uid(),_agency,auth.uid(),'Onboarding') RETURNING id INTO cid; INSERT INTO public.milestones(case_id,label,position) SELECT cid,label,ord FROM unnest(ARRAY['Onboarding','Assessment','Legal','Matching','IVF / Treatment','Pregnancy','Birth','Postpartum / Close-out']) WITH ORDINALITY AS s(label,ord); INSERT INTO public.financial_items(case_id,category,label,amount,created_by) VALUES(cid,'nestfam','Onboarding / case setup',150000,auth.uid()),(cid,'nestfam','Assessment / matching coordination',200000,auth.uid()),(cid,'nestfam','Treatment / clinical coordination',200000,auth.uid()),(cid,'nestfam','Pregnancy / completion coordination',200000,auth.uid()); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.create_agency_case(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_agency_case(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.manage_agency_access(_agency uuid,_entity uuid,_kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.agency_access(_agency,true) THEN RAISE EXCEPTION 'Agency administrator required'; END IF; IF _kind='member' THEN UPDATE public.agency_members SET active=false WHERE id=_entity AND agency_id=_agency AND user_id<>(SELECT owner_id FROM public.agencies WHERE id=_agency); ELSIF _kind='participant' THEN UPDATE public.case_participants SET active=false WHERE id=_entity AND case_id IN(SELECT id FROM public.cases WHERE agency_id=_agency); ELSIF _kind='invitation' THEN UPDATE public.agency_invitations SET status='revoked' WHERE id=_entity AND agency_id=_agency AND status='pending'; ELSE RAISE EXCEPTION 'Invalid action'; END IF; INSERT INTO public.audit_logs(agency_id,actor_id,action,entity,entity_id) VALUES(_agency,auth.uid(),'REVOKE',_kind,_entity); END $$;
REVOKE ALL ON FUNCTION public.manage_agency_access(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_agency_access(uuid,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_subscription_plan(_agency uuid,_plan text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE amt numeric; BEGIN IF NOT public.agency_access(_agency,true) THEN RAISE EXCEPTION 'Agency administrator required'; END IF; amt=CASE _plan WHEN 'starter' THEN 75000 WHEN 'professional' THEN 150000 WHEN 'growth' THEN 300000 WHEN 'enterprise' THEN 500000 ELSE NULL END; IF amt IS NULL THEN RAISE EXCEPTION 'Invalid plan'; END IF; UPDATE public.agencies SET plan=_plan WHERE id=_agency; UPDATE public.subscriptions SET plan=_plan,monthly_amount=amt,status='pilot' WHERE agency_id=_agency; INSERT INTO public.audit_logs(agency_id,actor_id,action,entity,entity_id) VALUES(_agency,auth.uid(),'PLAN_REQUEST','subscriptions',_agency); END $$;
REVOKE ALL ON FUNCTION public.record_subscription_plan(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_subscription_plan(uuid,text) TO authenticated;
CREATE POLICY cases_agency_insert_guard ON public.cases AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(false);
CREATE POLICY cases_write_guard ON public.cases AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.case_access(id,'general',true)) WITH CHECK(public.case_access(id,'general',true));
CREATE POLICY matching_private_read ON public.matches AS RESTRICTIVE FOR SELECT TO authenticated USING(case_id IS NOT NULL AND public.case_access(case_id,'medical'));
CREATE POLICY matching_no_peer_insert ON public.matches AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(false);
CREATE POLICY matching_no_peer_update ON public.matches AS RESTRICTIVE FOR UPDATE TO authenticated USING(false);
CREATE POLICY carriers_private_read ON public.surrogate_profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin() OR EXISTS(SELECT 1 FROM public.case_participants p WHERE p.user_id=surrogate_profiles.user_id AND p.active AND public.case_access(p.case_id,'medical')));
CREATE POLICY doc_private_read ON public.documents AS RESTRICTIVE FOR SELECT TO authenticated USING(owner_id=auth.uid() OR (case_id IS NOT NULL AND public.case_access(case_id,visibility_domain)));
CREATE POLICY doc_private_insert ON public.documents AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND signed_at IS NULL AND coalesce(cardinality(signed_by),0)=0 AND (case_id IS NULL OR public.case_access(case_id,visibility_domain)));
CREATE POLICY messages_domain_read ON public.messages AS RESTRICTIVE FOR SELECT TO authenticated USING(public.case_access(case_id,CASE channel WHEN 'Medical' THEN 'medical' WHEN 'Legal' THEN 'legal' WHEN 'Finance' THEN 'finance' ELSE 'messages' END));
CREATE POLICY messages_domain_send ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.case_access(case_id,CASE channel WHEN 'Medical' THEN 'medical' WHEN 'Legal' THEN 'legal' WHEN 'Finance' THEN 'finance' ELSE 'messages' END));
CREATE POLICY pregnancy_private_read ON public.pregnancy_updates AS RESTRICTIVE FOR SELECT TO authenticated USING(public.case_access(case_id,'medical'));
CREATE POLICY milestones_write_guard ON public.milestones AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.case_access(case_id,'general',true));
CREATE POLICY profiles_no_self_trust ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING(id=auth.uid() OR public.is_admin());
CREATE OR REPLACE FUNCTION public.guard_profile_trust() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.is_admin() AND (NEW.suspended IS DISTINCT FROM OLD.suspended OR NEW.id_verified IS DISTINCT FROM OLD.id_verified OR NEW.phone_verified IS DISTINCT FROM OLD.phone_verified OR NEW.selfie_verified IS DISTINCT FROM OLD.selfie_verified OR NEW.email_verified IS DISTINCT FROM OLD.email_verified OR (NEW.kyc_status IS DISTINCT FROM OLD.kyc_status AND NEW.kyc_status NOT IN('unstarted','pending'))) THEN RAISE EXCEPTION 'Trust fields require authorized review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_trust_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_trust();
CREATE POLICY verifications_self_guard ON public.verifications AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reviewer_notes IS NULL AND verification_scope IS NULL);
CREATE POLICY verifications_update_guard ON public.verifications AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_admin());
CREATE POLICY role_assignment_guard ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(false);
CREATE OR REPLACE FUNCTION public.record_onboarding_role(_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _role NOT IN('intended_parent','carrier','professional','clinic_staff','agency_staff','agency_admin') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND NOT suspended) THEN RAISE EXCEPTION 'Invalid onboarding'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),_role::public.app_role); END IF; INSERT INTO public.consents(user_id,kind) VALUES(auth.uid(),'platform_privacy_and_terms'); END $$;
REVOKE ALL ON FUNCTION public.record_onboarding_role(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_onboarding_role(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_case_assessment(_case uuid,_carrier uuid,_decision text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; aid uuid; pid uuid; BEGIN IF NOT public.case_access(_case,'medical',true) OR length(_decision) NOT BETWEEN 2 AND 2000 THEN RAISE EXCEPTION 'Professional assessment access required'; END IF; SELECT agency_id,parent_id INTO aid,pid FROM public.cases WHERE id=_case; IF NOT EXISTS(SELECT 1 FROM public.case_participants WHERE case_id=_case AND user_id=_carrier AND role='carrier' AND active) THEN RAISE EXCEPTION 'Carrier must be an authorized case participant'; END IF; INSERT INTO public.matches(case_id,agency_id,parent_id,surrogate_id,score,rationale,professional_decision,assessment_status,initiated_by) VALUES(_case,aid,pid,_carrier,0,'Recorded professional workflow',_decision,'reviewed',auth.uid()) RETURNING id INTO cid; INSERT INTO public.audit_logs(agency_id,case_id,actor_id,action,entity,entity_id) VALUES(aid,_case,auth.uid(),'ASSESSMENT','matches',cid); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.record_case_assessment(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_case_assessment(uuid,uuid,text) TO authenticated;